import csv

def read_csv_to_dicts(file_path):
    """
    Reads a CSV file and returns a list of dictionaries where each dictionary
    represents a row with column headers as keys.
    Supports basic formula evaluation for cells starting with '='.
    """
    data = []
    with open(file_path, mode='r', newline='', encoding='utf-8') as csvfile:
        reader = csv.DictReader(csvfile)
        for row in reader:
            processed_row = {}
            for key, value in row.items():
                if isinstance(value, str) and value.startswith('='):
                    try:
                        # Evaluate simple formulas safely
                        processed_row[key] = eval(value[1:], {'__builtins__': None}, {})
                    except:
                        processed_row[key] = value
                else:
                    processed_row[key] = value
            data.append(processed_row)
    return data
